// FindSetBuffered loads all filtered records into memory for bidirectional navigation
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *UserPreferences) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := UserPreferencesTableName
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT user_id, page_id, preference_type, preference_name, preference_data, created_at, updated_at FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.db.Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for User_Preferences: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &UserPreferences{}
		record.db = t.db
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var user_idNull sql.NullString
		var preference_typeNull sql.NullString
		var preference_nameNull sql.NullString
		var preference_dataNull sql.NullString
		var created_atNull sql.NullString
		var updated_atNull sql.NullString

		err := rows.Scan(
			&user_idNull,
			&record.Page_id,
			&preference_typeNull,
			&preference_nameNull,
			&preference_dataNull,
			&created_atNull,
			&updated_atNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan User_Preferences record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.User_id = types.NewCode(user_idNull.String)
		record.Preference_type = types.NewCode(preference_typeNull.String)
		record.Preference_name = types.NewCode(preference_nameNull.String)
		record.Preference_data = types.NewText(preference_dataNull.String)
		record.Created_at, _ = types.NewDateTimeFromString(created_atNull.String)
		record.Updated_at, _ = types.NewDateTimeFromString(updated_atNull.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate User_Preferences records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

